mapper.select:
SELECT t.follow_up_id, t.tenant_id, t.customer_id, t.opportunity_id, t.follow_up_type, t.follow_up_time, t.next_follow_up_time, t.content, t.result_summary, t.attachment_url, t.owner_id, t.owner_name, t.deleted, t.create_by, t.create_time, t.update_by, t.update_time, c.dept_id AS scope_dept_id, c.owner_id AS scope_owner_id FROM crm_follow_up t INNER JOIN crm_customer c ON c.customer_id = t.customer_id AND c.deleted = '0' WHERE t.deleted = '0'
AND t.customer_id = #{query.customerId}
AND t.opportunity_id = #{query.opportunityId}
AND t.owner_id = #{query.ownerId}
ORDER BY t.follow_up_time DESC
